def transform(grid):
    h, w = len(grid), len(grid[0])

    # The uniform full-length lines are the panel dividers.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(1, h))
    ]

    row_bounds = [-1] + divider_rows + [h]
    col_bounds = [-1] + divider_cols + [w]

    result = []
    for i in range(len(row_bounds) - 1):
        out_row = []
        for j in range(len(col_bounds) - 1):
            r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            count = sum(
                grid[r][c] == 5
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if count == 2 else 3)
        result.append(out_row)
    return result
